/* @lc app=leetcode id=3455 lang=kotlin */ class Solution { fun z(t: String): IntArray = IntArray(t.length).also { z -> (1 until t.length).fold(0 to 0) { (l, r), i -> (if (i < r) minOf(r - i, z[i - l]) else 0).let { k0 -> (k0 + generateSequence(k0) { it + 1 }.takeWhile { i + it < t.length && t[it] == t[i + it] }.count()).let { k -> z.set(i, k).let { if (i + k > r) i to i + k else l to r } } } } } fun occ(s: String, pat: String): BooleanArray = if (pat.isEmpty()) BooleanArray(s.length + 1) { true } else z(pat + "#" + s).let { zz -> BooleanArray(s.length + 1) { i -> i < s.length && zz[pat.length + 1 + i] >= pat.length } } fun shortestMatchingSubstring(s: String, p: String): Int = p.split("*").let { (a, b, c) -> occ(s, a).let { oa -> occ(s, b).let { ob -> occ(s, c).let { oc -> oa.indices.runningFold(-1) { last, i -> if (oa[i]) i else last }.drop(1).let { pa -> oc.indices.reversed().runningFold(Int.MAX_VALUE) { nx, i -> if (oc[i]) i else nx }.drop(1).reversed().let { nc -> s.length.let { n -> (0..n).filter { ob[it] && it - a.length >= 0 && it + b.length <= n }.mapNotNull { i -> pa[i - a.length].let { pst -> nc[i + b.length].let { cst -> if (pst >= 0 && cst != Int.MAX_VALUE) cst + c.length - pst else null } } }.minOrNull() ?: -1 } } } } } } } }